package com.example.examplemod.item;

import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;

public class WandItem extends Item {
    public WandItem(Properties props) {
        super(props);
    }

    @Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player,
                                                  InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        level.playSound(null, player.blockPosition(),
                SoundEvents.EXPERIENCE_ORB_PICKUP, SoundSource.PLAYERS, 1.0f, 1.0f);
        return InteractionResultHolder.success(stack);
    }
}

package com.example.examplemod.item;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.ItemStack;

public class WandChargeNBT {
    // getOrCreateTag is the canonical 1.20.1 item-NBT API
    // (removed in 1.20.5+ - that change belongs to the NeoForge target)
    public static int get(ItemStack stack) {
        CompoundTag tag = stack.getOrCreateTag();
        return tag.getInt("charge");
    }

    public static void set(ItemStack stack, int v) {
        stack.getOrCreateTag().putInt("charge", Math.max(0, v));
    }
}

