package com.example.examplemod.gameplay;

import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;

public class ItemUseGate {
    // server is authoritative: client-side use must not run gameplay logic
    public static boolean canUse(Player player, Level level) {
        if (level.isClientSide) return false;
        if (player.isSpectator()) return false;
        return true;
    }
}

package com.example.examplemod.gameplay;

import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;

public class BlockBreakGuard {
    public static boolean canBreak(Level level, BlockPos pos, Player p) {
        if (level.isClientSide) return false;
        if (!level.isLoaded(pos)) return false; // unloaded chunk
        if (level.getBlockState(pos).getBlock() == Blocks.BEDROCK) {
            return false;
        }
        return true;
    }
}

package com.example.examplemod.gameplay;

public class TickPhaseGate {
    private static long lastSeen = Long.MIN_VALUE;

    // production would use AtomicLong.compareAndSet for cross-thread safety
    public static boolean beginTick(long gameTime) {
        if (gameTime == lastSeen) return false;
        lastSeen = gameTime;
        return true;
    }

    public static void endTick() {
        // phase bookkeeping placeholder
    }
}

package com.example.examplemod.gameplay;

import net.minecraft.world.item.ItemStack;

import java.util.ArrayList;
import java.util.List;

public class PlayerDeathDropRule {
    public static List<ItemStack> dropsFor(int charge, ItemStack wand) {
        List<ItemStack> drops = new ArrayList<>();
        if (charge > 0 && !wand.isEmpty()) {
            drops.add(wand.copy());
        }
        return drops;
    }
