package com.example.examplemod.gameplay;

public class DimensionTravelGate {
    // self-dimension travel would loop; range check keeps portals local
    public static boolean canTravel(String fromDim, String toDim, int playerX,
                                    int portalX) {
        if (fromDim == null || toDim == null) return false;
        if (fromDim.equals(toDim)) return false;
        return Math.abs(playerX - portalX) <= 16;
    }
}

package com.example.examplemod.gameplay;

public class FallDamagePatch {
    public static float fallDamage(float fallDistance, boolean featherFalling) {
        float base = Math.max(0f, fallDistance - 3f);
        float v = featherFalling ? base / 2f : base;
        return Math.round(v * 100) / 100.0f;
    }
}

package com.example.examplemod.gameplay;

public class FoodValuesRule {
    public static int healFor(int nutrition, float saturation) {
        if (saturation < 0.8f) return nutrition;
        if (saturation < 1.2f) return Math.round(nutrition * 1.2f);
        return nutrition * 2;
    }
}

package com.example.examplemod.gameplay;

import java.util.Map;
import java.util.UUID;

public class InteractionCooldown {
    public static boolean tryUse(Map<UUID, Long> lastUse, UUID player,
                                 long nowMs, long cooldownMs) {
        Long last = lastUse.get(player);
        if (last != null && nowMs - last < cooldownMs) {
            return false;
        }
        lastUse.put(player, nowMs);
        return true;
    }
}

package com.example.examplemod.gameplay;

import net.minecraft.world.level.Level;

public class SideAwareFx {
    public static void burst(Level level, double x, double y, double z) {
        if (level.isClientSide) {
            // client: local particle is enough for self-triggered effects
            level.addParticle(net.minecraft.core.particles.ParticleTypes.SMOKE,
                    x, y, z, 0, 0.02, 0);
        } else {
            // server: particles must be broadcast via networking payload
            // (see group F tasks); direct addParticle is a server no-op
        }
    }
}

package com.example.examplemod.gameplay;

public class RepairCostRule {
    // vanilla flags 'too expensive' at >= 40 (not enforced here)
    public static int repairCost(int currentCost, int anvilUses) {
        long cost = currentCost;
        for (int i = 0; i < anvilUses; i++) {
            cost *= 2;
            if (cost >= Integer.MAX_VALUE) return Integer.MAX_VALUE;
        }
        return (int) Math.min(Integer.MAX_VALUE, cost);
    }
}

package com.example.examplemod.gameplay;

public class EnchantCompatRule {
    // vanilla protection variants are mutually exclusive
    public static boolean canCombine(String a, String b) {
        if (a == null || b == null) return false;
        if (a.equals(b)) return false;
        if (a.endsWith("mending") || b.endsWith("mending")) return true;
        boolean protA = a.endsWith("protection");
        boolean protB = b.endsWith("protection");
        return !(protA && protB);
    }
}

package com.example.examplemod.gameplay;

public class MobGriefingRule {
    public static boolean canGrief(String gameruleValue, boolean isTamed) {
        return "true".equals(gameruleValue) && !isTamed;
    }
}

package com.example.examplemod.gameplay;

public class PistonMoveRule {
    public static boolean canPush(String blockId) {
        if (blockId == null) return false;
        return !blockId.equals("minecraft:obsidian")
                && !blockId.equals("minecraft:bedrock")
                && !blockId.endsWith("_shrine");
    }
}

package com.example.examplemod.gameplay;

public class ExplosionRule {
    // real explosions ray-cast per block; this is the budget estimator
    public static int blocksDestroyed(float power, boolean inWater) {
        if (power <= 0 || inWater) return 0;
        return Math.round(power * power * 8);
    }
}

package com.example.examplemod.gameplay;

public class VillagerTradeRule {
    public static int priceFor(int basePrice, int demand) {
        int price = basePrice + Math.max(0, demand) / 5;
        return Math.max(1, Math.min(64, price));
    }
}

package com.example.examplemod.gameplay;

public class NetherPortalRule {
    // vanilla interior bounds: width [2,21], height [3,21]
    public static boolean isValidFrame(int width, int height) {
        return width >= 2 && width <= 21 && height >= 3 && height <= 21;
    }
}

package com.example.examplemod.gameplay;

public class BeaconEffectRule {
    // beacon pyramid: up to 4 layers (9x9 base)
    public static String effectFor(int pyramidLayers) {
        return switch (pyramidLayers) {
            case 1 -> "speed";
            case 2 -> "haste";
            case 3 -> "strength";
            case 4 -> "regeneration";
            default -> null;
        };
    }
}

package com.example.examplemod.gameplay;

public class RedstoneSignalRule {
    public static int outputSignal(int inputSignal, boolean powered,
                                   boolean inverted) {
        int v = Math.max(0, Math.min(15, inputSignal));
        if (!powered || v == 0) return 0;
        return inverted ? 15 - v : v;
    }
}

package com.example.examplemod.gameplay;

public class ItemFrameRotationRule {
    public static int nextRotation(int current, boolean scrollUp) {
        return ((current + (scrollUp ? 1 : -1)) % 8 + 8) % 8;
    }
}

package com.example.examplemod.gameplay;

public class ConduitRule {
    public static int frameBlocksNeeded(int frameBlocks) {
        if (frameBlocks < 14) return 0;
        return Math.min(64, 16 + (frameBlocks - 14));
    }
}

