package com.example.examplemod.client;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import org.lwjgl.glfw.GLFW;

public class TabOrderScreen extends Screen {
    private EditBox a;
    private EditBox b;
    private EditBox c;

    public TabOrderScreen() {
        super(Component.literal("Tab order"));
    }

    @Override
    protected void init() {
        a = addRenderableWidget(new EditBox(font, width / 2 - 100, 30, 200, 20,
                Component.literal("A")));
        b = addRenderableWidget(new EditBox(font, width / 2 - 100, 54, 200, 20,
                Component.literal("B")));
        c = addRenderableWidget(new EditBox(font, width / 2 - 100, 78, 200, 20,
                Component.literal("C")));
        setInitialFocus(a);
    }

    @Override
    public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
        if (keyCode == GLFW.GLFW_KEY_TAB) {
            var cur = getFocused();
            if (cur == a) setFocused(b);
            else if (cur == b) setFocused(c);
            else setFocused(a);
            return true;
        }
        return super.keyPressed(keyCode, scanCode, modifiers);
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        drawBorder(g, a);
        drawBorder(g, b);
        drawBorder(g, c);
        super.render(g, mouseX, mouseY, partialTick);
    }

    private void drawBorder(GuiGraphics g, EditBox box) {
        int color = getFocused() == box ? 0xFFFFFFFF : 0xFF555555;
        g.fill(box.getX() - 1, box.getY() - 1,
                box.getX() + box.getWidth() + 1, box.getY() + 21, color);
    }
}

package com.example.examplemod.client;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

public class StaleDataScreen extends Screen {
    public static final long STALE_MS = 5000;
    private static Integer lastValue;
    private static long lastUpdateMs;

    public StaleDataScreen() {
        super(Component.literal("Data"));
    }

    public static void accept(int value) {
        lastValue = value;
        lastUpdateMs = System.currentTimeMillis();
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        if (lastValue == null) {
            g.drawCenteredString(font, "no data", width / 2, height / 2, 0xFFAAAAAA);
        } else {
            long age = System.currentTimeMillis() - lastUpdateMs;
            String status = age < STALE_MS ? "fresh" : "stale";
            int color = age < STALE_MS ? 0xFF66FF66 : 0xFFCC6633;
            g.drawCenteredString(font, "value: " + lastValue,
                    width / 2, height / 2 - 10, 0xFFFFFF);
            g.drawCenteredString(font, status, width / 2, height / 2 + 4, color);
        }
        super.render(g, mouseX, mouseY, partialTick);
    }
}

