package com.example.examplemod.client;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.ItemStack;

public class InventoryPeekScreen extends Screen {
    public InventoryPeekScreen() {
        super(Component.literal("Inventory peek"));
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        if (minecraft == null || minecraft.player == null) {
            g.drawCenteredString(font, "not in world", width / 2, height / 2,
                    0xFF888888);
            super.render(g, mouseX, mouseY, partialTick);
            return;
        }
        int shown = 0;
        int y = 40;
        var items = minecraft.player.getInventory().getNonEquipmentItems();
        for (int i = 0; i < items.size() && shown < 5; i++) {
            ItemStack stack = items.get(i);
            if (stack.isEmpty()) continue;
            g.drawString(font, stack.getHoverName().getString(),
                    width / 2 - 80, y, 0xFFFFFF);
            shown++;
            y += 12;
        }
        super.render(g, mouseX, mouseY, partialTick);
    }
}

package com.example.examplemod.client;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

public class ServerErrorBannerScreen extends Screen {
    private static String lastError;
    private static long acceptedAt;
    private static final long SHOW_MS = 10_000;

    public ServerErrorBannerScreen() {
        super(Component.literal(""));
    }

    public static void acceptError(String msg) {
        lastError = (msg == null || msg.isBlank()) ? "internal error" : msg;
        acceptedAt = System.currentTimeMillis();
    }

    public static void clear() {
        lastError = null;
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        if (lastError != null
                && System.currentTimeMillis() - acceptedAt < SHOW_MS) {
            String text = lastError;
            while (font.width(text) > width - 20 && text.length() > 4) {
                text = text.substring(0, text.length() - 4) + "...";
            }
            g.fill(0, 0, width, 20, 0xFF662222);
            g.drawString(font, text, 10, 6, 0xFFFFFF);
        }
        super.render(g, mouseX, mouseY, partialTick);
    }
}

