package com.example.examplemod.client.render;

public class RenderLoopBudget {
    private static final float[] PRECOMPUTED_SIN = new float[360];

    static {
        for (int i = 0; i < 360; i++) {
            PRECOMPUTED_SIN[i] = (float) Math.sin(Math.toRadians(i));
        }
    }

    // 360 floats = 1.4 KB; removes per-frame Math.sin calls
    public static float fastSinDeg(int deg) {
        deg = ((deg % 360) + 360) % 360;
        return PRECOMPUTED_SIN[deg];
    }

    public static long allocationsGuard() {
        return 0L;
    }
}

