import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.CrowdBlockEntity;

public class CrowdBER implements BlockEntityRenderer<CrowdBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public CrowdBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    // rotating parts exceed the 1x1x1 block bounds: vanilla culling would
    // pop the whole render when the block is off-screen; infinite box opts out
    @Override
    public AABB getRenderBoundingBox() {
        return AABB.infinite();
    }

    @Override
    public void render(CrowdBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        for (int i = 0; i < 24; i++) {
            if (be.isHidden()) continue;
            double a = Math.toRadians(i * 15.0);
            pose.pushPose();
            pose.translate(0.5 + Math.cos(a) * 0.6, 0.1,
                    0.5 + Math.sin(a) * 0.6);
            pose.scale(0.05f, 0.05f, 0.05f);
            ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                    Blocks.EMERALD_BLOCK.defaultBlockState(), pose, buffers,
                    light, OverlayTexture.NO_OVERLAY);
            pose.popPose();
        }
    }
}

package com.example.examplemod.client.render;

public class FrustumDoc {
    // conservative: real culling uses camera-space frustum planes; this
    // distance test never hides a sphere that is actually visible
    public static boolean sphereIntersectsFrustumLike(
            double cx, double cy, double cz, double radius,
            double camX, double camY, double camZ, double maxDist) {
        double dx = cx - camX, dy = cy - camY, dz = cz - camZ;
        double limit = maxDist + radius;
        return dx * dx + dy * dy + dz * dz <= limit * limit;
    }

    public static double maxSafeRadius() {
        return 32.0;
    }
}

