import net.minecraft.world.level.block.state.BlockState;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.LazyModelBlockEntity;

public class LazyModelBER implements BlockEntityRenderer<LazyModelBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;
    private Integer cachedKey;
    private BlockState cachedState;

    public LazyModelBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    private BlockState stateFor(int variant) {
        if (cachedKey == null || cachedKey != variant) {
            cachedKey = variant;
            cachedState = switch (Math.floorMod(variant, 3)) {
                case 0 -> Blocks.STONE.defaultBlockState();
                case 1 -> Blocks.COBBLESTONE.defaultBlockState();
                default -> Blocks.MOSSY_COBBLESTONE.defaultBlockState();
            };
        }
        return cachedState;
    }

    @Override
    public void render(LazyModelBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        // note: on resource reload the cached state must be re-resolved;
        // the reload hook is out of scope for this exercise
        BlockState state = stateFor(be.getVariant());
        pose.pushPose();
        pose.translate(0.5, 0.15, 0.5);
        pose.scale(0.7f, 0.7f, 0.7f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                state, pose, buffers, light, OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

package com.example.examplemod.client.render;

public class CullingCorrectness {
    // conservative box-vs-sphere pre-pass used before frustum checks
    public static boolean isPotentiallyVisible(double[] min, double[] max,
                                               double[] cam, double maxDist) {
        double cx = Math.max(min[0], Math.min(max[0], cam[0]));
        double cy = Math.max(min[1], Math.min(max[1], cam[1]));
        double cz = Math.max(min[2], Math.min(max[2], cam[2]));
        double dx = cam[0] - cx, dy = cam[1] - cy, dz = cam[2] - cz;
        return dx * dx + dy * dy + dz * dz <= maxDist * maxDist;
    }
}

