package com.example.examplemod.client.render;

public class PoseStackAudit {
    // a leaked pushPose corrupts every subsequent render in the frame:
    // transforms accumulate and geometry drifts or disappears
    public static int audit(String[] ops) {
        int depth = 0;
        for (String op : ops) {
            if ("push".equals(op)) depth++;
            else if ("pop".equals(op)) depth--;
        }
        return depth;
    }

    public static boolean isBalanced(String[] ops) {
        return audit(ops) == 0;
    }

    public static String diagnose(String[] ops) {
        int depth = 0;
        for (String op : ops) {
            if ("push".equals(op)) depth++;
            else if ("pop".equals(op)) {
                depth--;
                if (depth < 0) return "underflow";
            }
        }
        return depth == 0 ? "ok" : "leak";
    }
}

