package com.example.examplemod.client.render;

public class VertexOrderDoc {
    // winding matters for backface culling: CCW quads survive in GUI space
    public static double signedArea(double[][] tri) {
        return 0.5 * ((tri[1][0] - tri[0][0]) * (tri[1][1] + tri[0][1])
                + (tri[2][0] - tri[1][0]) * (tri[2][1] + tri[1][1])
                + (tri[0][0] - tri[2][0]) * (tri[0][1] + tri[2][1]));
    }

    public static boolean isCounterClockwise(double[][] tri) {
        return signedArea(tri) > 0;
    }
}

